BEGIN;


-- ── Office: 9 submarkets (each with vacancy + stock-weighted rent) ──
DELETE FROM office_market_benchmarks WHERE city='Bengaluru';


-- ── Retail: 12 high-street corridors ──
DELETE FROM retail_market_benchmarks WHERE city='Bengaluru' AND format='high_street';


-- ── Industrial / Warehouse / Land: 10 submarkets ──
DELETE FROM industrial_market_benchmarks WHERE city='Bengaluru';


-- ── Hospitality: 2 clusters ──
DELETE FROM hospitality_market_benchmarks WHERE city='Bengaluru';


-- ── Micro-market: 27 listing-portal + 14 IPC zone rows ──
DELETE FROM micro_market_benchmarks WHERE city='Bengaluru' AND data_type IN ('listing_q1_2026','ipc_q1_2026','listing_q1_2026_v0_2','ipc_q1_2026_v0_2');


